UPDATE rj_countries SET is_destination = 1,
    capital = 'Bangkok',
    languages = 'Thai',
    timezone = 'UTC+7',
    plug_types = 'A, B, C, O',
    best_season = 'November to February (cool and dry)',
    summary = 'Golden temples, island-dotted seas, misty northern mountains and some of the world''s best street food, at prices that stretch a budget a long way.',
    history = 'Thai kingdoms rose at Sukhothai (13th century) and Ayutthaya (1351–1767), which became one of Asia''s great trading cities before it fell to Burmese armies. The capital moved to Thonburi and then Bangkok in 1782 under the Chakri dynasty, which still reigns. Thailand is the only Southeast Asian country never colonised by a European power, and it became a constitutional monarchy in 1932.',
    culture = 'Daily life mixes Buddhist ritual with a love of food, festivals and sanuk (fun). Major festivals include Songkran, the Thai New Year water festival in April, and Loy Krathong in November, when people float candle-lit offerings on rivers.',
    beliefs = 'About 93% of Thais are Theravada Buddhists. Spirit houses outside homes and businesses receive daily offerings of food, flowers and incense, and the monarchy is held in deep respect.',
    etiquette = 'Dress modestly at temples (shoulders and knees covered, shoes off inside). Never touch someone''s head or point your feet at people or Buddha images. Criticising the royal family is a serious crime. Greet with a wai (palms together) and keep your voice calm; losing your temper causes loss of face.',
    cost_index = 2,
    price_meal = 60,
    price_coffee = 70,
    price_hotel_night = 1500,
    price_local_transport = 30,
    emergency_police = '191',
    emergency_ambulance = '1669',
    emergency_fire = '199',
    tourist_police = '1155',
    advisory_level = 1,
    advisory_url = 'https://travel.state.gov/traveladvisories'
WHERE iso2 = 'TH';
UPDATE rj_countries SET is_destination = 1,
    capital = 'Tokyo',
    languages = 'Japanese',
    timezone = 'UTC+9',
    plug_types = 'A, B',
    best_season = 'Late March to May (cherry blossom) and October to November (autumn leaves)',
    summary = 'Neon megacities and quiet temple gardens side by side, spotless trains that run to the minute, and food culture taken to an art form.',
    history = 'Kyoto was the imperial capital for over a thousand years (794–1868) while samurai shoguns held real power. After two centuries of near isolation under the Tokugawa shogunate, the 1868 Meiji Restoration moved the capital to Tokyo and launched rapid modernisation. Rebuilt after World War II, Japan became one of the world''s largest economies.',
    culture = 'Respect for others, punctuality and attention to detail shape everyday life. Seasonal traditions such as hanami (cherry-blossom viewing) and summer matsuri festivals sit alongside anime, gaming and fashion subcultures.',
    beliefs = 'Most people follow a blend of Shinto, which honours kami spirits at shrines, and Buddhism, which shapes funerals and temple life. Many visit a shrine at New Year and a temple for memorials.',
    etiquette = 'Don''t eat while walking in busy streets, and keep phone calls off trains. Tipping is not expected and can cause confusion. Remove shoes where you see a step up or slippers at the entrance. Queue patiently, and carry your rubbish with you because public bins are rare.',
    cost_index = 4,
    price_meal = 1000,
    price_coffee = 500,
    price_hotel_night = 15000,
    price_local_transport = 200,
    emergency_police = '110',
    emergency_ambulance = '119',
    emergency_fire = '119',
    tourist_police = '050-3816-2787',
    advisory_level = 1,
    advisory_url = 'https://travel.state.gov/traveladvisories'
WHERE iso2 = 'JP';
UPDATE rj_countries SET is_destination = 1,
    capital = 'Rome',
    languages = 'Italian',
    timezone = 'UTC+1 (UTC+2 in summer)',
    plug_types = 'C, F, L',
    best_season = 'April to June and September to October',
    summary = 'Ancient Roman ruins, Renaissance masterpieces and a food culture built on simple, excellent ingredients.',
    history = 'Rome grew from a small settlement into an empire that ruled the Mediterranean for centuries. After the Western Empire fell in 476, the peninsula split into city-states and papal lands. Florence led the Renaissance in the 15th century, and Italy only became one unified country in 1861.',
    culture = 'Family, food and the evening passeggiata (stroll) are at the heart of daily life. Each region guards its own dishes, dialects and traditions, and lunch is often the main meal of the day.',
    beliefs = 'Italy is predominantly Roman Catholic, and Vatican City, the seat of the Pope, sits inside Rome. Church festivals and patron saints'' days are celebrated in towns across the country.',
    etiquette = 'Cover shoulders and knees in churches. Cappuccino is a morning drink; ordering one after a meal marks you as a tourist. A coperto (cover charge) on the bill is normal. Validate bus and train tickets before travelling or you can be fined.',
    cost_index = 4,
    price_meal = 15,
    price_coffee = 1.5,
    price_hotel_night = 150,
    price_local_transport = 1.5,
    emergency_police = '113',
    emergency_ambulance = '118',
    emergency_fire = '115',
    tourist_police = '112 (EU emergency number)',
    advisory_level = 2,
    advisory_url = 'https://travel.state.gov/traveladvisories'
WHERE iso2 = 'IT';
