VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), 'Chiang Mai', 'เชียงใหม่', 18.7883, 98.9853, 'mixed', 2, 'November to February', 'The laid-back capital of the north, with a moated old city full of temples and the country''s highest mountains an hour away.', 'Founded in 1296 by King Mangrai as the capital of the Lanna Kingdom, which kept its own language, script and art until it became part of Siam in the 19th century.')
