VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'JP'), 'Tokyo', 'โตเกียว', 35.6762, 139.6503, 'urban', NULL, 'March to May, October to November', 'A city of neighbourhoods, from neon Shibuya to old-town Asakusa, with world-class food at every price.', 'Originally the fishing village of Edo, it became the shogun''s seat in 1603 and was renamed Tokyo ("eastern capital") when the emperor moved there in 1868.')
