VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'EG'), 'Cairo', 'ไคโร', 30.0444, 31.2357, 'urban', NULL, 'October to April', 'Africa''s largest city, home to the Giza pyramids, medieval Islamic streets and the world''s greatest collection of pharaonic treasures.', 'Founded in 969 by the Fatimid dynasty next to much older settlements, including ancient Memphis and the Roman fortress of Babylon.')
