VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'EG'), 'Luxor', 'ลักซอร์', 25.6872, 32.6396, 'mixed', 1, 'October to April', 'Built on ancient Thebes: vast temples on the east bank, royal tombs in the desert hills on the west bank, and the Nile between them.', 'As Thebes, it was the capital of Egypt during the New Kingdom (about 1550–1070 BC), when pharaohs such as Tutankhamun and Ramesses II were buried in the Valley of the Kings.')
