INSERT INTO rj_places (city_id, category_id, name_en, name_th, summary, description, history, culture_beliefs, how_to_get_there, address, lat, lng, price_level, price_min, price_max, environment, terrain, is_historical, difficulty, duration_hours, permit_required, permit_info, opening_hours, dress_code, status)
SELECT (SELECT id FROM rj_cities WHERE name_en = 'Bangkok'), (SELECT id FROM rj_categories WHERE slug = 'attraction'), 'The Grand Palace and Wat Phra Kaew', 'พระบรมมหาราชวัง และวัดพระแก้ว', 'The dazzling former royal residence and home of the Emerald Buddha, Thailand''s most sacred image.', 'A walled complex of gilded halls, mosaic-covered stupas and mythical guardian statues. Wat Phra Kaew, inside the grounds, houses the small jade Emerald Buddha.', 'Built in 1782 when King Rama I moved the capital across the river to Bangkok. Kings lived here until the early 20th century.', 'The Emerald Buddha''s robes are changed by the King three times a year, at the start of the hot, rainy and cool seasons.', 'Chao Phraya Express Boat to Tha Chang pier, then a 5-minute walk.', 'Na Phra Lan Rd, Phra Nakhon, Bangkok', 13.75, 100.4913, 3, 500, 500, 'urban', 'city', 1, NULL, 2.5, 0, NULL, '08:30–15:30 daily', 'Shoulders and knees covered; remove shoes inside buildings', 'published'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_places WHERE name_en = 'The Grand Palace and Wat Phra Kaew' AND city_id = (SELECT id FROM rj_cities WHERE name_en = 'Bangkok'));
INSERT IGNORE INTO rj_place_tags (place_id, tag_id)
SELECT (SELECT id FROM rj_places WHERE name_en = 'The Grand Palace and Wat Phra Kaew' LIMIT 1), id FROM rj_tags WHERE slug IN ('history', 'religious', 'culture', 'photo_spot');
INSERT INTO rj_places (city_id, category_id, name_en, name_th, summary, description, history, culture_beliefs, how_to_get_there, address, lat, lng, price_level, price_min, price_max, environment, terrain, is_historical, difficulty, duration_hours, permit_required, permit_info, opening_hours, dress_code, status)
SELECT (SELECT id FROM rj_cities WHERE name_en = 'Bangkok'), (SELECT id FROM rj_categories WHERE slug = 'attraction'), 'Wat Arun', 'วัดอรุณราชวราราม', 'The Temple of Dawn, whose porcelain-studded spire rises above the Chao Phraya River.', 'Climb the steep steps of the central prang for river views, then cross back at sunset to see it lit up from the east bank.', 'An old riverside temple that King Taksin chose as his royal temple after the fall of Ayutthaya. The 70 m prang was built in the early 19th century.', NULL, 'Cross-river ferry from Tha Tien pier, next to Wat Pho.', NULL, 13.7437, 100.4888, 1, 200, 200, 'urban', 'river', 1, NULL, 1, 0, NULL, '08:00–18:00 daily', 'Shoulders and knees covered; remove shoes inside buildings', 'published'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_places WHERE name_en = 'Wat Arun' AND city_id = (SELECT id FROM rj_cities WHERE name_en = 'Bangkok'));
INSERT IGNORE INTO rj_place_tags (place_id, tag_id)
SELECT (SELECT id FROM rj_places WHERE name_en = 'Wat Arun' LIMIT 1), id FROM rj_tags WHERE slug IN ('history', 'religious', 'photo_spot', 'night_view');
