SELECT (SELECT id FROM rj_cities WHERE name_en = 'Chiang Mai'), (SELECT id FROM rj_categories WHERE slug = 'attraction'), 'Wat Phra That Doi Suthep', 'วัดพระธาตุดอยสุเทพ', 'A golden hilltop temple with views over the whole city.', 'Climb the 306-step naga staircase (or take the funicular) to the gilded chedi said to hold a relic of the Buddha.', 'Founded in 1383. Legend says a white elephant carrying the relic climbed the mountain, trumpeted and died on this spot.', NULL, 'Red songthaew from the zoo or Chiang Mai University, about 30 minutes.', NULL, 18.8049, 98.9216, 1, 30, 50, 'mixed', 'mountain', 1, NULL, 2, 0, NULL, '06:00–18:00 daily', 'Shoulders and knees covered; remove shoes inside buildings', 'published'
