SELECT (SELECT id FROM rj_cities WHERE name_en = 'Chiang Mai'), (SELECT id FROM rj_categories WHERE slug = 'attraction'), 'Wat Chedi Luang', 'วัดเจดีย์หลวง', 'The massive ruined chedi in the heart of the old city.', 'Its top collapsed in an earthquake in 1545. Join a free "monk chat" to ask monks about Buddhist life.', 'Begun in the late 14th century; at about 80 m it was once the tallest structure in Lanna. It held the Emerald Buddha for 80 years.', NULL, NULL, NULL, 18.7869, 98.9866, 1, 50, 50, 'urban', 'city', 1, NULL, 1, 0, NULL, NULL, 'Shoulders and knees covered; remove shoes inside buildings', 'published'
