SELECT (SELECT id FROM rj_cities WHERE name_en = 'Chiang Mai'), (SELECT id FROM rj_categories WHERE slug = 'trail'), 'Kew Mae Pan Nature Trail', 'เส้นทางศึกษาธรรมชาติกิ่วแม่ปาน', 'A 3 km ridge walk through cloud forest and grassland in Doi Inthanon National Park.', 'Famous for sunrise views over a sea of mist in the cool season. The walk takes 2–3 hours at a relaxed pace.', NULL, NULL, 'About 2 hours'' drive from Chiang Mai along the road to the Doi Inthanon summit.', NULL, 18.5537, 98.484, 1, 300, 500, 'nature', 'mountain', 0, 2, 3, 1, 'Must be walked with a local Hmong guide hired at the trailhead (about 200 THB per group). National park entry fee applies.', 'Usually 1 November to 31 May; closed in the rainy season', NULL, 'published'
