SELECT (SELECT id FROM rj_cities WHERE name_en = 'Chiang Mai'), (SELECT id FROM rj_categories WHERE slug = 'market'), 'Sunday Walking Street', 'ถนนคนเดินวันอาทิตย์', 'Ratchadamnoen Road turns into a kilometre-long market of crafts and street food every Sunday evening.', 'Look for hill-tribe textiles, carved soap and khao soi stalls. It gets very crowded after 19:00.', NULL, NULL, 'Starts at Tha Phae Gate.', NULL, 18.788, 98.989, 1, NULL, NULL, 'urban', 'city', 0, NULL, 2.5, 0, NULL, 'Sundays, about 16:00–22:30', NULL, 'published'
