SELECT (SELECT id FROM rj_cities WHERE name_en = 'Kyoto'), (SELECT id FROM rj_categories WHERE slug = 'trail'), 'Fushimi Inari Taisha', 'ศาลเจ้าฟูชิมิ อินาริ', 'Thousands of vermilion torii gates climbing a forested mountain.', 'The full loop to the summit takes 2–3 hours. Most crowds turn back at the Yotsutsuji viewpoint halfway up.', 'Founded in 711, it is the head shrine of Inari, the kami of rice and business. Each gate is donated by a company or family.', 'The fox statues are Inari''s messengers; many hold a key to the rice granary in their mouths.', 'JR Inari Station, directly in front of the shrine.', NULL, 34.9671, 135.7727, 0, NULL, NULL, 'mixed', 'mountain', 1, 2, 3, 0, NULL, 'Always open', NULL, 'published'
