FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM rj_risk_scores WHERE country_id = (SELECT id FROM rj_countries WHERE iso2 = 'TH') AND city_id IS NULL AND risk_type = 'crime_violent');
