-- Visa rules for Thai passport holders ---------------------------------------
INSERT INTO rj_visa_rules (nationality_country_id, destination_country_id, visa_type, max_stay_days, fee_text, summary, how_to_apply, official_url, verified_at)
VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), (SELECT id FROM rj_countries WHERE iso2 = 'JP'), 'visa_free', 15, 'Free', 'Ordinary Thai passport holders can visit Japan without a visa for up to 15 days per visit. Japan extended this arrangement from 1 July 2026 to 30 June 2027.', 'No visa needed for tourism of 15 days or less. For longer stays or work, apply for a visa at the Embassy of Japan in Bangkok.', 'https://www.th.emb-japan.go.jp/', '2026-10-28')
AS new ON DUPLICATE KEY UPDATE visa_type = new.visa_type, max_stay_days = new.max_stay_days, fee_text = new.fee_text,
    summary = new.summary, how_to_apply = new.how_to_apply, official_url = new.official_url, verified_at = new.verified_at;
INSERT INTO rj_visa_rules (nationality_country_id, destination_country_id, visa_type, max_stay_days, fee_text, summary, how_to_apply, official_url, verified_at)
VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), (SELECT id FROM rj_countries WHERE iso2 = 'IT'), 'visa_required', 90, 'EUR 90 (Schengen short-stay visa)', 'Thai citizens need a Schengen short-stay visa, which allows up to 90 days in any 180-day period across the Schengen area.', 'Book an appointment at the Italian visa centre in Bangkok. Bring your passport, flight and hotel bookings, travel insurance of at least EUR 30,000 and proof of funds. Apply at least 3–4 weeks before travel.', 'https://ambbangkok.esteri.it/', NULL)
AS new ON DUPLICATE KEY UPDATE visa_type = new.visa_type, max_stay_days = new.max_stay_days, fee_text = new.fee_text,
    summary = new.summary, how_to_apply = new.how_to_apply, official_url = new.official_url, verified_at = new.verified_at;
INSERT INTO rj_visa_rules (nationality_country_id, destination_country_id, visa_type, max_stay_days, fee_text, summary, how_to_apply, official_url, verified_at)
VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), (SELECT id FROM rj_countries WHERE iso2 = 'EG'), 'visa_required', 30, 'About USD 25 (single entry)', 'Thai citizens need a visa for Egypt. Sources disagree on whether the e-Visa and visa on arrival are open to Thai passports, so confirm with the Egyptian Embassy in Bangkok before booking.', 'Check eligibility on the official e-Visa portal, visa2egypt.gov.eg. If Thailand isn''t listed, apply at the Egyptian Embassy in Bangkok. Your passport must be valid for at least 6 months.', 'https://www.visa2egypt.gov.eg/', NULL)
AS new ON DUPLICATE KEY UPDATE visa_type = new.visa_type, max_stay_days = new.max_stay_days, fee_text = new.fee_text,
    summary = new.summary, how_to_apply = new.how_to_apply, official_url = new.official_url, verified_at = new.verified_at;
INSERT INTO rj_visa_rules (nationality_country_id, destination_country_id, visa_type, max_stay_days, fee_text, summary, how_to_apply, official_url, verified_at)
VALUES ((SELECT id FROM rj_countries WHERE iso2 = 'TH'), (SELECT id FROM rj_countries WHERE iso2 = 'PE'), 'visa_free', 90, 'Free', 'Thai citizens do not need a tourist visa for Peru and can stay up to 90 days.', 'No visa needed. Bring a passport valid for at least 6 months from entry and a return or onward ticket.', 'https://www.peruthai.or.th/visas.php', '2026-10-28')
AS new ON DUPLICATE KEY UPDATE visa_type = new.visa_type, max_stay_days = new.max_stay_days, fee_text = new.fee_text,
    summary = new.summary, how_to_apply = new.how_to_apply, official_url = new.official_url, verified_at = new.verified_at;
